package com.bank.pipeline;

import java.util.logging.Logger;

public class PipelineReachability {

    private static final Logger log = Logger.getLogger(PipelineReachability.class.getName());

    public boolean canReachEnd(int[] jumps) {
        int reach = 0;                                 // farthest index reachable so far
        for (int i = 0; i < jumps.length; i++) {
            if (i > reach) {                           // stranded before this index
                final int frontier = reach;
                log.warning(() -> "Stuck: cannot pass index " + frontier);
                return false;
            }
            reach = Math.max(reach, i + jumps[i]);     // extend the frontier
        }
        log.info("Last stage reachable");
        return true;
    }
}
