package com.bank.pipeline;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class JumpGameDemo {

    private static final Logger log = Logger.getLogger(JumpGameDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Pipeline Reachability (Jump Game)");
        PipelineReachability pipeline = new PipelineReachability();
        log.info("{2,3,1,1,4} → " + pipeline.canReachEnd(new int[]{2, 3, 1, 1, 4})); // true
        log.info("{3,2,1,0,4} → " + pipeline.canReachEnd(new int[]{3, 2, 1, 0, 4})); // false
    }
}
